package util_test

import (
	"testing"
	"github.com/pingcap/tidb/util/hack"
	"github.com/stretchr/testify/assert"
)

func TestMutableString(t *testing.T) {
	t.Run("String", func(t *testing.T) {
		m := hack.String([]byte("hello"))
		assert.Equal(t, "hello", m)
	})

	t.Run("Slice", func(t *testing.T) {
		s := hack.Slice("hello")
		assert.Equal(t, []byte("hello"), s)
	})

	t.Run("String and Slice conversion", func(t *testing.T) {
		m := hack.String([]byte("hello"))
		s := hack.Slice(m)
		assert.Equal(t, []byte("hello"), s)
	})

	t.Run("EstimateBucketMemoryUsage", func(t *testing.T) {
		t.Run("String", func(t *testing.T) {
			m := EstimateBucketMemoryUsage(hack.String([]byte("hello")))
			assert.Equal(t, uint64(DefBucketMemoryUsageForMapStrToSlice), m)
		})

		t.Run("Int64", func(t *testing.T) {
			m := EstimateBucketMemoryUsage(hack.String([]byte("hello")))
			assert.Equal(t, uint64(DefBucketMemoryUsageForMapIntToPtr), m)
		})

		t.Run("Any", func(t *testing.T) {
			m := EstimateBucketMemoryUsage(hack.String([]byte("hello")))
			assert.Equal(t, uint64(DefBucketMemoryUsageForMapStringToAny), m)
		})

		t.Run("SetString", func(t *testing.T) {
			m := EstimateBucketMemoryUsage(hack.String([]byte("hello")))
			assert.Equal(t, uint64(DefBucketMemoryUsageForSetString), m)
		})

		t.Run("SetFloat64", func(t *testing.T) {
			m := EstimateBucketMemoryUsage(hack.String([]byte("hello")))
			assert.Equal(t, uint64(DefBucketMemoryUsageForSetFloat64), m)
		})

		t.Run("SetInt64", func(t *testing.T) {
			m := EstimateBucketMemoryUsage(hack.String([]byte("hello")))
			assert.Equal(t, uint64(DefBucketMemoryUsageForSetInt64), m)
		})
	})
}

